var n=`0792-langouste-a-la-vanille`;var t=`world-0792`;var a=`KM`;var s=`eastern-africa`;var l=4;var o=66;var r={en:`Langouste à la Vanille`,ua:`Лангуст із ваніллю`};var u={en:`Langouste à la Vanille is a Comoros classic prepared with spiny lobster, lemon juice, garlic, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Лангуст із ваніллю, страва кухні країни Коморські Острови зі складниками: лангуст, лимонний сік, часник, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`spiny-lobster`,850,`g`],[`lemon-juice`,35,`ml`],[`garlic`,4,`clove`],[`table-salt`,null,`to_taste`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,160,`g`],[`unsalted-butter`,60,`g`],[`vanilla-bean`,1,`pcs`]]},{en:`Grill lobster tail or split lobster over moderate heat until the flesh is fully opaque and cooked, avoiding drying.`,ua:`Готуйте хвости або половинки лангуста на грилі над помірним жаром до повної готовності непрозорого м’яса, не пересушуючи.`,t:[`grilling`],m:16,i:[[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 8 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 8 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:8,i:[[`heavy-cream`,170,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,15,`g`]]}];var d={slug:n,id:t,country:`KM`,region:s,servings:4,minutes:66,title:r,text:u,steps:g};export{a as country,d as default,t as id,o as minutes,s as region,l as servings,n as slug,g as steps,u as text,r as title};